function showParaMenu(open){paraMenu.hidden=!open;paraToggle.setAttribute('aria-expanded',String(open));if(open){setFileMenu(false);tools(false);positionParas()}}
paraToggle.onclick=()=>showParaMenu(paraMenu.hidden);
